users=[next((t.get('value') or '' for t in (d.get('conversations') or []) if t.get('from')=='user'), '') for d in data]
assts=[next((t.get('value') or '' for t in (d.get('conversations') or []) if t.get('from')=='assistant'), '') for d in data]
def words(s): return set(re.findall(r'[A-Za-z0-9_]{4,}', s.lower()))
for i,m in enumerate(meta):
