    mp=words(m['problem']); mr=words(m['deepseek_reasoning']); ms=words(m['deepseek_solution'])
    best=[]
    for j,u in enumerate(users):
        score=len(mp & words(u))
        if score>=5: best.append((score,j))
    best.sort(reverse=True)
    print(i, m['domain'], 'best user word overlap', best[:5])
